-void FileSystemNoteLoader::deleteNoteResources(const QString &id)
+void FileSystemNoteLoader::deleteNoteResources(const QString &id, uint appletId)
 {
+    if (m_appletToId.value(appletId) == id) {
+        m_appletToId.remove(appletId);
+        m_sharingApplets.remove(appletId);
+    }
+    if (m_appletToId.values().contains(id)) {
+        return;
+    }
+
     const QUrl url = QUrl::fromLocalFile(m_notesDir.absoluteFilePath(id));
     KIO::Job *job = KIO::trash(url);
     if (!job->exec()) {
         m_notesDir.remove(id);
     }
-    m_idToApplet.remove(id);
 }

-Note *FileSystemNoteLoader::loadNote(const QString &id, uint appletId)
+Note *FileSystemNoteLoader::loadNote(const QString &id, uint appletId, bool shared)
 {
     QString idToUse = id;

     if (idToUse.isEmpty()) {
         idToUse = QUuid::createUuid().toString().mid(1, 34);
-        m_idToApplet.insert(idToUse, appletId);
-    } else {
-        if (m_idToApplet.contains(id)) {
-            uint existingApplet = m_idToApplet.value(id);
-            if (existingApplet != appletId) {
-                // If two applets are using the same note id, which can
-                // happen if e.g. the panel is cloned, we copy the
+    } else if (!shared) {
+        for (auto it = m_appletToId.cbegin(); it != m_appletToId.cend(); ++it) {
+            if (it.key() != appletId && it.value() == id && !m_sharingApplets.contains(it.key())) {
+                // If two applets are using the same note id as their own,
+                // which can happen if e.g. the panel is cloned, we copy the
                 // note file to a new id and assign one file per applet.
-                // This avoids having different applets using the same
-                // file.
+                // Applets only use another applet's note when asked to.
                 idToUse = QUuid::createUuid().toString().mid(1, 34);
                 QFile::copy(m_notesDir.absoluteFilePath(id), m_notesDir.absoluteFilePath(idToUse));
-                m_idToApplet.insert(idToUse, appletId);
+                break;
             }
-        } else {
-            m_idToApplet.insert(idToUse, appletId);
         }
     }

+    m_appletToId.insert(appletId, idToUse);
+    if (shared) {
+        m_sharingApplets.insert(appletId);
+    } else {
+        m_sharingApplets.remove(appletId);
+    }
+
     return new FileNote(m_notesDir.absoluteFilePath(idToUse), idToUse);
 }

+QVariantList FileSystemNoteLoader::otherNotes(uint appletId)
+{
+    QVariantList notes;
+    QStringList ids;
+    const QString ownId = m_sharingApplets.contains(appletId) ? QString() : m_appletToId.value(appletId);
+    for (auto it = m_appletToId.cbegin(); it != m_appletToId.cend(); ++it) {
+        if (it.key() == appletId || it.value() == ownId || ids.contains(it.value())) {
+            continue;
+        }
+        ids.append(it.value());
+
+        QString text;
+        QFile file(m_notesDir.absoluteFilePath(it.value()));
+        if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
+            const QStringList lines = QTextDocumentFragment::fromHtml(QString::fromUtf8(file.readAll())).toPlainText().split(QLatin1Char('\n'));
+            for (const QString &line : lines) {
+                if (!line.trimmed().isEmpty()) {
+                    text = line.trimmed();
+                    break;
+                }
+            }
+        }
+        notes.append(QVariantMap{{QStringLiteral("id"), it.value()}, {QStringLiteral("text"), text}});
+    }
+    return notes;
+}
+
